def compute(vars):
    try:
        number_of_securities = vars["v1"]
        weighted_average_exercise_price = vars["v2"]
        total_value_dollars = number_of_securities * weighted_average_exercise_price
        total_value_millions = total_value_dollars / 1000000

        return {
            "value": total_value_millions,
            "trace": {
                "number_of_securities": number_of_securities,
                "weighted_average_exercise_price": weighted_average_exercise_price,
                "total_value_dollars": total_value_dollars,
                "output_meta": {
                    "currency": "USD",
                    "scale": "millions",
                    "unit": "currency"
                }
            }
        }
    except ZeroDivisionError:
        return None
